'use client';
import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { cssEase, duration as D, profileScale, useStudioMotion } from '../../../motion';
import { FleetChart, N, type ChartData } from './FleetChart';
import { AGENTS, SEED, advance, createStore, statusOf, type FleetEvent, type Severity, type Status, type Store } from './sim';
import s from './styles.module.css';

const WINDOWS = [{ sec: 60, label: '1 min', name: 'one minute' }, { sec: 300, label: '5 min', name: 'five minutes' }, { sec: 900, label: '15 min', name: 'fifteen minutes' }] as const;
type WindowSec = (typeof WINDOWS)[number]['sec'];
const STATUS_LABEL: Record<Status, string> = { healthy: 'Healthy', degraded: 'Degraded', failing: 'Failing', paused: 'Paused' };
const SEV_LABEL: Record<Severity, string> = { critical: 'Critical', major: 'Major', resolved: 'Cleared' };
const ANNOUNCE_EVERY = 15_000;
const hms = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: 'UTC' });
const int = new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 });
const pct1 = new Intl.NumberFormat('en-GB', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });
const pct2 = new Intl.NumberFormat('en-GB', { style: 'percent', minimumFractionDigits: 2, maximumFractionDigits: 2 });
const signedPct = new Intl.NumberFormat('en-GB', { style: 'percent', signDisplay: 'exceptZero', maximumFractionDigits: 0 });
const at = (tick: number) => hms.format(tick * 1000);
const iso = (tick: number) => new Date(tick * 1000).toISOString();

/** Resample positions [from, to] of a buffer to N points: bucket mean/max when longer, linear when shorter. */
function resample(src: number[], from: number, to: number, how: 'mean' | 'max'): Float64Array {
  const out = new Float64Array(N);
  const len = to - from + 1;
  for (let k = 0; k < N; k++) {
    if (len >= N) {
      const s0 = from + Math.floor((k * len) / N), s1 = from + Math.floor(((k + 1) * len) / N) - 1;
      let acc = how === 'max' ? 0 : 0, c = 0;
      for (let j = s0; j <= Math.max(s0, s1); j++) { const v = src[j]; if (!Number.isFinite(v)) continue; acc = how === 'max' ? Math.max(acc, v) : acc + v; c++; }
      out[k] = c ? (how === 'max' ? acc : acc / c) : 0;
    } else {
      const u = from + (k / (N - 1)) * (len - 1), j = Math.min(to - 1, Math.floor(u)), f = u - j;
      const v0 = src[j], v1 = src[Math.min(to, j + 1)];
      out[k] = Number.isFinite(v0) && Number.isFinite(v1) ? v0 + (v1 - v0) * f : 0;
    }
  }
  return out;
}

function Glyph({ kind }: { kind: Status | Severity }) {
  return (
    <svg viewBox="0 0 12 12" aria-hidden="true" className={s.glyph} data-kind={kind}>
      {kind === 'failing' || kind === 'critical' ? <path d="M4 .8h4L11.2 4v4L8 11.2H4L.8 8V4z" />
        : kind === 'degraded' || kind === 'major' ? <path d="M6 .9 11.4 10.9H.6z" />
        : kind === 'paused' ? <path d="M2.5 1.5h2.4v9H2.5zM7.1 1.5h2.4v9H7.1z" />
        : kind === 'resolved' ? <path d="M1.8 6.4 4.8 9.2 10.4 2.9" className={s.glyphStroke} />
        : <rect x="1.5" y="1.5" width="9" height="9" rx="1" />}
    </svg>
  );
}

function Spark({ values, flags }: { values: Float64Array; flags: Uint8Array }) {
  let max = 0;
  for (const v of values) max = Math.max(max, v);
  const h = 36, w = 160, n = values.length;
  const px = (k: number) => (k / (n - 1)) * w, py = (v: number) => h - 2 - (v / (max * 1.1 || 1)) * (h - 4);
  let d = '';
  values.forEach((v, k) => { d += `${k ? 'L' : 'M'}${px(k).toFixed(1)} ${py(v).toFixed(1)}`; });
  const runs: [number, number][] = [];
  flags.forEach((f, k) => { if (!f) return; const last = runs[runs.length - 1]; if (last && last[1] === k - 1) last[1] = k; else runs.push([k, k]); });
  return (
    <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className={s.spark} aria-hidden="true">
      {runs.map(([a, b]) => { const x0 = Math.min(w - 5, Math.max(0, px(a) - 1)); return <rect key={a} x={x0} y={0} width={Math.min(w - x0, Math.max(5, px(b) - px(a) + 2))} height={h} className={s.sparkFlag} />; })}
      <line x1={0} x2={w} y1={h - 1} y2={h - 1} className={s.sparkBase} />
      <path d={d} className={s.sparkLine} />
    </svg>
  );
}

export default function LiveMonitoring() {
  const uid = useId();
  const { reduced } = useStudioMotion();
  const store = useRef<Store | null>(null);
  const [view, setView] = useState<number | null>(null);
  const [paused, setPaused] = useState(false);
  const pausedRef = useRef(paused);
  pausedRef.current = paused;
  const [win, setWin] = useState<WindowSec>(300);
  const [sel, setSel] = useState<number | null>(null);
  const [hold, setHold] = useState<number | null>(null);
  const holdSrc = useRef({ pointer: false, focus: false });
  const [showTable, setShowTable] = useState(false);
  const [announce, setAnnounce] = useState('');
  const ann = useRef({ lastAt: 0, lastTick: 0 });
  const ping = useRef<HTMLSpanElement>(null);

  // The stream starts after mount (its clock is the wall clock), so the server render is the designed loading state.
  useEffect(() => {
    const st = createStore(Math.floor(Date.now() / 1000));
    store.current = st;
    ann.current.lastTick = st.n;
    setView(st.n);
    const id = window.setInterval(() => {
      const now = Math.floor(Date.now() / 1000);
      advance(st, now);
      if (!pausedRef.current) setView(st.n);
    }, 1000);
    return () => { window.clearInterval(id); store.current = null; };
  }, []);

  const st = store.current;
  const ready = st !== null && view !== null && view >= st.n0;
  const end = ready ? view - st.n0 : 0;
  const start = Math.max(0, end - win + 1);

  // One brief ring per received tick; nothing pulses while paused or under reduced motion.
  useEffect(() => {
    const el = ping.current;
    if (!el || reduced || paused || typeof el.animate !== 'function') return;
    // One ring per received sample, from tokens (Essential: slow × 0.7 ≈ 390 ms), over well before the next tick.
    const a = el.animate([{ transform: 'scale(1)', opacity: 0.5 }, { transform: 'scale(2.4)', opacity: 0 }], { duration: D.slow * profileScale.essential.duration, easing: cssEase('standard') });
    return () => a.cancel();
  }, [view, reduced, paused]);

  // Polite announcements: new anomalies only, summarised, at most once every 15 s.
  useEffect(() => {
    if (!st || view === null || paused) return;
    const now = Date.now();
    if (now - ann.current.lastAt < ANNOUNCE_EVERY) return;
    const fresh = st.events.filter((e) => e.tick > ann.current.lastTick && e.tick <= view && e.severity !== 'resolved');
    ann.current.lastTick = view;
    if (!fresh.length) return;
    ann.current.lastAt = now;
    setAnnounce(fresh.length === 1
      ? `New anomaly on ${AGENTS[fresh[0].agent].id}: ${fresh[0].text}.`
      : `${fresh.length} new anomalies: ${fresh.slice(0, 3).map((e) => `${AGENTS[e.agent].id} ${e.kind}`).join(', ')}${fresh.length > 3 ? ' and more' : ''}.`);
  }, [view, st, paused]);

  const togglePause = () => {
    const next = !paused;
    setPaused(next);
    if (!next && st) { setView(st.n); ann.current.lastTick = st.n; }
    setAnnounce(next ? `Stream paused at ${view !== null ? at(view) : ''} UTC. Data keeps arriving in the background.` : 'Stream resumed; showing the latest data.');
  };

  const agentNow = AGENTS.map((spec, i) => {
    if (!ready) return { spec, i, status: 'healthy' as Status, rpm: NaN, p95: NaN, err: NaN, flags: 0 };
    const flags = st.flag[i][end];
    return { spec, i, status: statusOf(st, i, flags), rpm: st.rpm[i][end], p95: st.p95[i][end], err: st.err[i][end], flags };
  });
  const active = agentNow.filter((a) => !a.spec.paused);
  const fleet = useMemo(() => {
    if (!ready) return null;
    let sum = 0, failed = 0;
    for (const a of active) { sum += a.rpm; failed += a.rpm * a.err; }
    let wSum = 0;
    for (let j = start; j <= end; j++) for (const a of active) wSum += st.rpm[a.i][j];
    const avg = wSum / (end - start + 1);
    return { sum, failed, success: sum ? 1 - failed / sum : 1, avg };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view, win, ready]);

  const openCount = agentNow.reduce((c, a) => c + ((a.flags & 1) ? 1 : 0) + ((a.flags & 2) ? 1 : 0) + ((a.flags & 4) ? 1 : 0), 0);
  const healthy = active.filter((a) => a.status === 'healthy').length;
  const worst = active.reduce<(typeof active)[number] | null>((w, a) => (!w || a.p95 / a.spec.p95 > w.p95 / w.spec.p95 ? a : w), null);

  const selAgent = sel !== null ? AGENTS[sel] : null;
  const chart = useMemo<ChartData | null>(() => {
    if (!ready) return null;
    const t0 = st.n0 + start, t1 = view;
    if (sel === null) {
      const tot: number[] = [], fail: number[] = [];
      for (let j = 0; j <= end; j++) {
        let a = 0, f = 0;
        for (const ag of active) { const r = st.rpm[ag.i][j]; a += r; f += r * st.err[ag.i][j]; }
        tot.push(a); fail.push(f);
      }
      const markers = st.events.filter((e) => e.tick >= t0 && e.tick <= t1 && e.severity !== 'resolved').map((e) => ({ tick: e.tick, severity: e.severity as 'critical' | 'major' }));
      return { mode: 'fleet', a: resample(tot, start, end, 'mean'), b: resample(fail, start, end, 'mean'), c: null, flags: null, t0, t1, markers };
    }
    const f = st.flag[sel];
    const fl = new Uint8Array(N);
    const len = end - start + 1;
    for (let k = 0; k < N; k++) {
      const s0 = start + Math.floor((k * len) / N), s1 = Math.max(s0, start + Math.floor(((k + 1) * len) / N) - 1);
      for (let j = s0; j <= Math.min(end, s1); j++) if (f[j] & 1) { fl[k] = 1; break; }
    }
    return { mode: 'agent', a: resample(st.p95[sel], start, end, 'max'), b: resample(st.lo[sel], start, end, 'mean'), c: resample(st.hi[sel], start, end, 'mean'), flags: fl, t0, t1, markers: [] };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [view, win, sel, ready]);

  const winInfo = WINDOWS.find((w) => w.sec === win)!;
  const chartSummary = !ready || !chart ? 'Connecting to the simulated stream.'
    : chart.mode === 'fleet'
      ? (() => {
        let lo = Infinity, hi = 0;
        for (const v of chart.a) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
        const opened = chart.markers.length;
        return `Fleet runs per minute over the last ${winInfo.name}: ${int.format(fleet!.sum)} now, between ${int.format(lo)} and ${int.format(hi)}; ${pct2.format(fleet!.failed / Math.max(1, fleet!.sum))} of runs failing now. ${opened === 0 ? 'No anomalies opened' : `${opened} ${opened === 1 ? 'anomaly' : 'anomalies'} opened`} in this window.`;
      })()
      : selAgent?.paused ? `${selAgent.id} is paused by an operator; there is no data to show.`
      : (() => {
        const p = st.p95[sel!].slice(start, end + 1);
        const flaggedS = st.flag[sel!].slice(start, end + 1).filter((x) => x & 1).length;
        return `${selAgent!.id} p95 latency over the last ${winInfo.name}: ${int.format(p[p.length - 1])} ms now, peak ${int.format(Math.max(...p))} ms. Above its expected band (2-minute baseline ± 3σ) for ${flaggedS} s of this window.`;
      })();

  const logN = hold ?? view ?? 0;
  const visibleEvents: FleetEvent[] = ready ? st.events.filter((e) => e.tick <= logN).slice(-60).reverse() : [];
  const pending = ready && hold !== null && view !== null ? st.events.filter((e) => e.tick > hold && e.tick <= view).length : 0;
  const setHolding = (src: 'pointer' | 'focus', on: boolean) => {
    holdSrc.current[src] = on;
    const any = holdSrc.current.pointer || holdSrc.current.focus;
    setHold((h) => (any ? (h ?? view) : null));
  };

  const age = ready ? Math.max(0, Math.floor(Date.now() / 1000) - view) : 0;
  const state = !ready ? 'connecting' : paused ? 'paused' : age > 3 ? 'stale' : 'live';
  const kpiDelta = fleet ? fleet.sum / Math.max(1, fleet.avg) - 1 : 0;

  return (
    <div className={s.root} data-state={state} data-reduced={reduced || undefined}>
      <header className={s.bar}>
        <div className={`${s.wrap} ${s.barInner}`}>
          <div className={s.brand}>
            <p className={s.house}>Larkline Freight · fictional</p>
            <h2 className={s.name}>Switchyard <span className={s.nameSub}>agent fleet</span></h2>
          </div>
          <div className={s.liveBox} aria-live="off">
            <span className={s.lamp} data-state={state} aria-hidden="true"><span ref={ping} className={s.ping} /></span>
            <span className={s.stateWord}>{state === 'connecting' ? 'Connecting' : state === 'paused' ? 'Paused' : state === 'stale' ? 'Stale' : 'Live'}</span>
            <span className={s.stateMeta}>
              {ready ? <>{state === 'paused' ? 'showing' : 'updated'} <time dateTime={iso(view)}>{at(view)} UTC</time>{paused && st.n > view ? ` · ${st.n - view} s behind` : ''}</> : 'simulated stream'}
            </span>
            <span className={s.simBadge}>Simulated</span>
          </div>
          <fieldset className={s.windows}>
            <legend className={s.windowLegend}>Window</legend>
            {WINDOWS.map((w) => (
              <label key={w.sec} className={s.seg}>
                <input type="radio" name={`${uid}-win`} checked={win === w.sec} onChange={() => setWin(w.sec)} />
                <span>{w.label}</span>
              </label>
            ))}
          </fieldset>
          <button type="button" className={s.pause} aria-pressed={paused} onClick={togglePause} disabled={!ready}>
            <svg viewBox="0 0 12 12" aria-hidden="true">{paused ? <path d="M3 1.5v9l7.5-4.5z" /> : <path d="M2.5 1.5h2.4v9H2.5zM7.1 1.5h2.4v9H7.1z" />}</svg>
            {paused ? 'Resume stream' : 'Pause stream'}
          </button>
        </div>
      </header>

      <div className={s.wrap}>
        <p className={s.intro}>
          Eleven running agents for a fictional freight company, one sample per second. Anomaly rules run on the stream as it arrives; the log keeps still while you read it.
          Everything here is generated in your browser from seed {SEED} — no real systems, models or customers.
        </p>

        <section aria-labelledby={`${uid}-kpi`}>
          <h3 id={`${uid}-kpi`} className={s.srOnly}>Fleet now</h3>
          <dl className={s.kpis}>
            <div className={s.kpi}><dt>Runs per minute</dt><dd className={s.kpiValue}>{fleet ? int.format(fleet.sum) : '—'}</dd><dd className={s.kpiNote}>{fleet ? <><span className={s.dir}>{kpiDelta >= 0 ? '▲' : '▼'}</span> {signedPct.format(kpiDelta)} vs {winInfo.label} average</> : 'waiting for data'}</dd></div>
            <div className={s.kpi}><dt>Success rate</dt><dd className={s.kpiValue}>{fleet ? pct2.format(fleet.success) : '—'}</dd><dd className={s.kpiNote}>{fleet ? `${int.format(fleet.failed)} failing runs / min` : 'waiting for data'}</dd></div>
            <div className={s.kpi}><dt>Agents healthy</dt><dd className={s.kpiValue}>{ready ? <>{healthy}<span className={s.of}> / {active.length}</span></> : '—'}</dd><dd className={s.kpiNote}>{AGENTS.length - active.length} paused by an operator</dd></div>
            <div className={s.kpi} data-alert={openCount > 0 || undefined}><dt>Open anomalies</dt><dd className={s.kpiValue}>{ready ? openCount : '—'}</dd><dd className={s.kpiNote}>{ready ? (openCount ? agentNow.filter((a) => a.flags).map((a) => a.spec.id).join(', ') : 'None right now') : 'waiting for data'}</dd></div>
            <div className={s.kpi}><dt>Furthest above normal</dt><dd className={s.kpiValue}>{worst ? <>{int.format(worst.p95)}<span className={s.of}> ms</span></> : '—'}</dd><dd className={s.kpiNote}>{worst ? `${worst.spec.id} p95, ${signedPct.format(worst.p95 / worst.spec.p95 - 1)} vs its norm` : 'waiting for data'}</dd></div>
          </dl>
        </section>

        <div className={s.main}>
          <div className={s.primary}>
            <section className={s.panel} aria-labelledby={`${uid}-chart`}>
              <div className={s.panelHead}>
                <div>
                  <h3 id={`${uid}-chart`} className={s.panelTitle}>{selAgent ? <>{selAgent.id} <span className={s.titleMuted}>p95 latency, ms</span></> : <>Fleet throughput <span className={s.titleMuted}>runs per minute</span></>}</h3>
                  <p className={s.sub}>Last {winInfo.label} · 1-second samples · UTC · <span className={s.simTag}>Simulated</span></p>
                </div>
                {selAgent ? <button type="button" className={s.btn} onClick={() => setSel(null)}>Back to fleet</button> : null}
              </div>
              <ul className={s.legend} aria-label="Legend">
                {sel === null ? (<>
                  <li><span className={s.keyOk} aria-hidden="true" />All runs</li>
                  <li><span className={s.keyFail} aria-hidden="true" />Failed runs (lower band)</li>
                  <li><Glyph kind="major" />Anomaly opened</li>
                  <li><Glyph kind="critical" />Error-rate anomaly</li>
                </>) : (<>
                  <li><span className={s.keyLine} aria-hidden="true" />p95 latency</li>
                  <li><span className={s.keyBand} aria-hidden="true" />Expected: 2-min baseline ± 3σ</li>
                  <li><span className={s.keyFlag} aria-hidden="true" />Anomaly: above 3σ for 3 s or more</li>
                </>)}
              </ul>
              {chart && !(selAgent?.paused) ? (
                <FleetChart data={chart} modeKey={sel === null ? 'fleet' : `agent-${sel}`} windowKey={win} label={chartSummary} />
              ) : (
                <div className={s.plotEmpty}><p>{ready ? 'Paused by an operator at the start of this session — no samples to plot.' : 'Connecting to the simulated stream…'}</p></div>
              )}
              <p className={s.summary}>{chartSummary}</p>
            </section>

            <section className={s.panel} aria-labelledby={`${uid}-grid`}>
              <div className={s.panelHead}>
                <div>
                  <h3 id={`${uid}-grid`} className={s.panelTitle}>Agents</h3>
                  <p className={s.sub}>Now · sparklines show p95 latency over the last {winInfo.label}, each on its own scale from zero; shaded spans are anomalies. Choose an agent to chart it.</p>
                </div>
                <button type="button" className={s.btn} aria-expanded={showTable} aria-controls={`${uid}-table`} onClick={() => setShowTable((v) => !v)}>{showTable ? 'Hide table' : 'View as table'}</button>
              </div>
              <ul className={s.agents}>
                {agentNow.map((a) => {
                  const kinds = [a.flags & 1 ? 'latency' : null, a.flags & 2 ? 'errors' : null, a.flags & 4 ? 'throughput' : null].filter(Boolean);
                  return (
                    <li key={a.spec.id}>
                      <button type="button" className={s.tile} data-status={a.status} aria-pressed={sel === a.i} onClick={() => setSel((x) => (x === a.i ? null : a.i))}>
                        <span className={s.tileHead}>
                          <span className={s.status} data-status={a.status}><Glyph kind={a.status} />{STATUS_LABEL[a.status]}</span>
                          <span className={s.tier}>Tier {a.spec.tier}</span>
                        </span>
                        <span className={s.agentId}>{a.spec.id}</span>
                        <span className={s.role}>{a.spec.role}</span>
                        {a.spec.paused ? (
                          <span className={s.tileEmpty}>No samples while paused</span>
                        ) : (<>
                          <span className={s.tileValue}>{ready ? int.format(a.p95) : '—'}<span className={s.unit}> ms p95</span></span>
                          {ready ? <Spark values={resample(st.p95[a.i], start, end, 'max').filter((_, k) => k % 4 === 0)} flags={Uint8Array.from({ length: N / 4 }, (_, k) => {
                            const len = end - start + 1, s0 = start + Math.floor((k * 4 * len) / N), s1 = start + Math.floor(((k * 4 + 4) * len) / N) - 1;
                            for (let j = s0; j <= Math.min(end, Math.max(s0, s1)); j++) if (st.flag[a.i][j] & 1) return 1;
                            return 0;
                          })} /> : <span className={s.sparkEmpty} />}
                          <span className={s.tileMeta}>{ready ? `${int.format(a.rpm)} runs/min · ${pct1.format(a.err)} errors` : 'waiting for data'}</span>
                          {kinds.length ? <span className={s.anomaly}>Anomaly · {kinds.join(', ')}</span> : null}
                        </>)}
                      </button>
                    </li>
                  );
                })}
              </ul>
              <div id={`${uid}-table`} hidden={!showTable} className={s.tableBox} role="region" aria-label="Agents, table" tabIndex={showTable ? 0 : -1}>
                {showTable ? (
                  <table className={s.table}>
                    <caption className={s.caption}>Agent values at {ready ? `${at(view)} UTC` : '—'}{paused ? ' (paused)' : ''}. Simulated data.</caption>
                    <thead><tr><th scope="col">Agent</th><th scope="col">Status</th><th scope="col" className={s.num}>Runs / min</th><th scope="col" className={s.num}>p95 (ms)</th><th scope="col" className={s.num}>Errors</th><th scope="col">Open anomalies</th></tr></thead>
                    <tbody>
                      {agentNow.map((a) => (
                        <tr key={a.spec.id}>
                          <th scope="row">{a.spec.id}</th>
                          <td>{STATUS_LABEL[a.status]}</td>
                          <td className={s.num}>{a.spec.paused || !ready ? '—' : int.format(a.rpm)}</td>
                          <td className={s.num}>{a.spec.paused || !ready ? '—' : int.format(a.p95)}</td>
                          <td className={s.num}>{a.spec.paused || !ready ? '—' : pct1.format(a.err)}</td>
                          <td>{[a.flags & 1 ? 'latency' : null, a.flags & 2 ? 'errors' : null, a.flags & 4 ? 'throughput' : null].filter(Boolean).join(', ') || '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : null}
              </div>
            </section>
          </div>

          <section className={`${s.panel} ${s.logPanel}`} aria-labelledby={`${uid}-log`}>
            <div className={s.panelHead}>
              <div>
                <h3 id={`${uid}-log`} className={s.panelTitle}>Event log</h3>
                <p className={s.sub}>Newest first · UTC · rules: latency above 3σ for 3 s; errors at 2% for 3 s; throughput under 50% for 5 s</p>
              </div>
            </div>
            <p className={s.holdNote} data-on={hold !== null || undefined}>
              {hold !== null ? <>Held while you read{pending ? ` · ${pending} new` : ''} </> : 'Updates live; hover or focus the log to hold it.'}
              {hold !== null && pending ? <button type="button" className={s.linkBtn} onClick={() => setHold(view)}>Show {pending} new</button> : null}
            </p>
            <div
              className={s.log} role="region" aria-labelledby={`${uid}-log`} tabIndex={0}
              onPointerEnter={() => setHolding('pointer', true)} onPointerLeave={() => setHolding('pointer', false)}
              onFocus={() => setHolding('focus', true)}
              onBlur={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setHolding('focus', false); }}
            >
              {visibleEvents.length ? (
                <ol className={s.events}>
                  {visibleEvents.map((e) => (
                    <li key={e.id} className={s.event} data-sev={e.severity}>
                      <time dateTime={iso(e.tick)} className={s.evTime}>{at(e.tick)}</time>
                      <span className={s.evSev} data-sev={e.severity}><Glyph kind={e.severity} />{SEV_LABEL[e.severity]}</span>
                      <span className={s.evAgent}>{AGENTS[e.agent].id}</span>
                      <span className={s.evText}>{e.text}</span>
                    </li>
                  ))}
                </ol>
              ) : <p className={s.empty}>{ready ? 'No events in the last 15 minutes.' : 'Connecting to the simulated stream…'}</p>}
            </div>
          </section>
        </div>

        <footer className={s.foot}>
          <p><strong>Data note.</strong> Simulated stream, seed {SEED}: each one-second sample is a pure function of agent and time — seeded smooth noise, jitter, and incidents placed by hashing four-minute blocks. Anomaly rules run on it exactly as they would on a live feed. Agent names are invented; no models, customers or systems are real. Pausing freezes the view while data keeps arriving; resuming jumps to the latest second.</p>
        </footer>
      </div>
      <p className={s.srOnly} role="status" aria-live="polite">{announce}</p>
    </div>
  );
}

'use client';
/**
 * Fleet / agent time-series panel. Every window is resampled to N points, so switching 1 → 5 → 15 minutes
 * interpolates the values and the y-domain together (the line-chart-morph recipe's technique, effects/line-chart-morph);
 * live ticks and agent switches redraw directly — a change of metric has no meaningful in-between state.
 */
import { useEffect, useMemo, useRef, useState } from 'react';
import { easeCubicInOut, scaleLinear } from 'd3';
import { duration as D, profileScale, useElementSize, useStudioMotion } from '../../../motion';
import s from './styles.module.css';

export const N = 240;
export interface ChartData {
  mode: 'fleet' | 'agent';
  /** fleet: total runs/min, failed runs/min. agent: p95 ms, expected band low/high, anomaly flags. */
  a: Float64Array;
  b: Float64Array;
  c: Float64Array | null;
  flags: Uint8Array | null;
  t0: number;
  t1: number;
  markers: { tick: number; severity: 'critical' | 'major' }[];
}
interface Shown { a: Float64Array; b: Float64Array; c: Float64Array | null; yMax: number; yMax2: number }

const M = { top: 18, right: 10, bottom: 24, left: 46 };
const nf = new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 });
const hm = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'UTC' });
const hms = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false, timeZone: 'UTC' });

const niceMax = (arr: Float64Array, min = 1): number => {
  let m = 0;
  for (const v of arr) m = Math.max(m, v);
  return scaleLinear().domain([0, Math.max(min, m) * 1.1]).nice(3).domain()[1];
};
const yMaxOf = (d: ChartData): number => {
  let m = 0;
  for (const v of d.a) m = Math.max(m, v);
  if (d.mode === 'agent' && d.c) for (const v of d.c) m = Math.max(m, v);
  return scaleLinear().domain([0, Math.max(1, m) * 1.08]).nice(4).domain()[1];
};

export function FleetChart({ data, modeKey, windowKey, label }: { data: ChartData; modeKey: string; windowKey: number; label: string }) {
  const { reduced } = useStudioMotion();
  const ref = useRef<HTMLDivElement>(null);
  const { width, height } = useElementSize(ref);
  const target: Shown = useMemo(() => ({ a: data.a, b: data.b, c: data.c, yMax: yMaxOf(data), yMax2: data.mode === 'fleet' ? niceMax(data.b, 4) : 1 }), [data]);
  const [shown, setShown] = useState<Shown>(target);
  const live = useRef(target);
  live.current = target;
  const shownRef = useRef(shown);
  shownRef.current = shown;
  const keys = useRef({ modeKey, windowKey });
  const tween = useRef(0);

  useEffect(() => {
    const prev = keys.current;
    keys.current = { modeKey, windowKey };
    if (prev.modeKey !== modeKey || reduced) { cancelAnimationFrame(tween.current); tween.current = 0; setShown(target); return; }
    if (prev.windowKey === windowKey) { if (!tween.current) setShown(target); return; }
    cancelAnimationFrame(tween.current);
    const from = shownRef.current;
    // Essential profile: a window switch is an axis rescale, `moderate` × 0.7.
    const dur = D.moderate * profileScale.essential.duration;
    let t0 = 0;
    const lerp = (p: Float64Array, q: Float64Array, e: number) => { const o = new Float64Array(N); for (let k = 0; k < N; k++) o[k] = p[k] + (q[k] - p[k]) * e; return o; };
    const frame = (now: number) => {
      if (!t0) t0 = now;
      const p = Math.min(1, (now - t0) / dur);
      const to = live.current; // retarget to the latest tick every frame
      if (p >= 1) { tween.current = 0; setShown(to); return; }
      const e = easeCubicInOut(p);
      setShown({ a: lerp(from.a, to.a, e), b: lerp(from.b, to.b, e), c: from.c && to.c ? lerp(from.c, to.c, e) : to.c, yMax: from.yMax + (to.yMax - from.yMax) * e, yMax2: from.yMax2 + (to.yMax2 - from.yMax2) * e });
      tween.current = requestAnimationFrame(frame);
    };
    tween.current = requestAnimationFrame(frame);
  }, [target, modeKey, windowKey, reduced]);
  useEffect(() => () => cancelAnimationFrame(tween.current), []);

  const innerW = Math.max(0, width - M.left - M.right);
  const innerH = Math.max(0, height - M.top - M.bottom);
  const ready = innerW > 40 && innerH > 40;
  // Fleet mode: two aligned bands on one time axis — all runs, then failed runs on their own zero-based scale.
  const fleet = data.mode === 'fleet';
  const GAP = 26;
  const topH = fleet ? Math.round((innerH - GAP) * 0.6) : innerH;
  const y = scaleLinear().domain([0, shown.yMax]).range([M.top + topH, M.top]);
  const y2 = scaleLinear().domain([0, shown.yMax2]).range([M.top + innerH, M.top + topH + GAP]);
  const x = (k: number) => M.left + (k / (N - 1)) * innerW;
  const xt = (tick: number) => M.left + ((tick - data.t0) / Math.max(1, data.t1 - data.t0)) * innerW;
  const pathOf = (arr: Float64Array, sy = y) => { let d = ''; for (let k = 0; k < N; k++) d += `${k ? 'L' : 'M'}${x(k).toFixed(1)} ${sy(arr[k]).toFixed(1)}`; return d; };
  const areaOf = (top: Float64Array, bottom: Float64Array | null, sy = y) => {
    let d = pathOf(top, sy);
    for (let k = N - 1; k >= 0; k--) d += `L${x(k).toFixed(1)} ${sy(bottom ? bottom[k] : 0).toFixed(1)}`;
    return `${d}Z`;
  };
  const flagged = () => {
    if (!data.flags) return '';
    let d = '';
    for (let k = 0; k < N; k++) if (data.flags[k]) d += `${k && data.flags[k - 1] ? 'L' : 'M'}${x(k).toFixed(1)} ${y(shown.a[k]).toFixed(1)}`;
    return d;
  };

  const span = data.t1 - data.t0;
  const stepS = span <= 60 ? 15 : span <= 300 ? 60 : 180;
  const ticks: number[] = [];
  for (let t = Math.ceil(data.t0 / stepS) * stepS; t <= data.t1; t += stepS) ticks.push(t);

  return (
    <div ref={ref} className={s.plot} role="img" aria-label={label}>
      {ready && (
        <svg width={width} height={height} aria-hidden="true" className={s.svg}>
          {[{ sc: y, n: fleet ? 3 : 4, key: 'a' }, ...(fleet ? [{ sc: y2, n: 2, key: 'b' }] : [])].map(({ sc, n, key }) => sc.ticks(n).map((v) => (
            <g key={`${key}${v}`} transform={`translate(0 ${sc(v).toFixed(1)})`}>
              <line x1={M.left} x2={M.left + innerW} className={v === 0 ? s.baseline : s.grid} />
              <text x={M.left - 8} y={4} textAnchor="end" className={s.tick}>{nf.format(v)}</text>
            </g>
          )))}
          {fleet && (
            <>
              <text x={M.left + 6} y={M.top + 12} className={s.bandLabel}>All runs / min</text>
              <text x={M.left + 6} y={M.top + topH + GAP + 12} className={s.bandLabel}>Failed runs / min · own scale</text>
            </>
          )}
          {ticks.map((t) => {
            const px = xt(t);
            return (
              <text key={t} x={px} y={M.top + innerH + 17} textAnchor={px < M.left + 24 ? 'start' : px > M.left + innerW - 24 ? 'end' : 'middle'} className={s.tick}>
                {(span <= 60 ? hms : hm).format(t * 1000)}
              </text>
            );
          })}
          {data.mode === 'fleet' ? (
            <>
              <path d={areaOf(shown.a, null)} className={s.okArea} />
              <path d={pathOf(shown.a)} className={s.okLine} />
              <path d={areaOf(shown.b, null, y2)} className={s.failArea} />
              {data.markers.map((m, i) => {
                const px = xt(m.tick);
                return m.severity === 'critical'
                  ? <rect key={i} x={px - 4} y={M.top - 13} width={8} height={8} className={s.markCritical} transform={`rotate(45 ${px} ${M.top - 9})`} />
                  : <path key={i} d={`M${px} ${M.top - 14}l5 9h-10z`} className={s.markMajor} />;
              })}
            </>
          ) : (
            <>
              {shown.c && <path d={areaOf(shown.c, shown.b)} className={s.band} />}
              <path d={pathOf(shown.a)} className={s.agentLine} />
              <path d={flagged()} className={s.flagLine} />
            </>
          )}
        </svg>
      )}
    </div>
  );
}

/**
 * Switchyard — a SIMULATED stream for a fictional freight company's fleet of AI agents.
 * Each sample is a pure function of (seed, agent, tick), where a tick is one wall-clock second: smooth seeded
 * value-noise for the daily texture, per-tick jitter, and seeded incidents (latency spikes, error bursts,
 * throughput drops) placed by hashing (agent, 4-minute block). Anomaly rules then run over the stream exactly
 * as they would over a real feed; swap `sampleAt()` for a real client and nothing else changes.
 */
export const SEED = 4127;
/** 15 minutes of one-second ticks are kept for display. */
export const CAPACITY = 900;
const WARMUP = 240;
const BASELINE = 120;

export type Tier = 'S' | 'M' | 'L';
export interface AgentSpec { id: string; role: string; tier: Tier; rpm: number; p95: number; err: number; paused?: boolean }
export const AGENTS: readonly AgentSpec[] = [
  { id: 'intake-triage', role: 'Sorts inbound shipper email', tier: 'S', rpm: 48, p95: 1400, err: 0.004 },
  { id: 'invoice-reader', role: 'Extracts invoice fields', tier: 'M', rpm: 36, p95: 2600, err: 0.006 },
  { id: 'customs-docs', role: 'Drafts customs declarations', tier: 'L', rpm: 12, p95: 5200, err: 0.008 },
  { id: 'route-planner', role: 'Plans multi-drop routes', tier: 'L', rpm: 20, p95: 3800, err: 0.003 },
  { id: 'claims-assist', role: 'Summarises damage claims', tier: 'M', rpm: 9, p95: 4400, err: 0.005 },
  { id: 'driver-chat', role: 'Answers driver questions', tier: 'S', rpm: 64, p95: 900, err: 0.002 },
  { id: 'rate-quoter', role: 'Quotes spot rates', tier: 'M', rpm: 30, p95: 1800, err: 0.004 },
  { id: 'dock-scheduler', role: 'Books loading-dock slots', tier: 'S', rpm: 16, p95: 2100, err: 0.003 },
  { id: 'returns-desk', role: 'Handles return requests', tier: 'M', rpm: 22, p95: 1600, err: 0.005 },
  { id: 'eta-notifier', role: 'Sends arrival updates', tier: 'S', rpm: 80, p95: 600, err: 0.002 },
  { id: 'contract-check', role: 'Flags unusual contract clauses', tier: 'L', rpm: 5, p95: 8800, err: 0.006, paused: true },
  { id: 'ledger-recon', role: 'Reconciles carrier invoices', tier: 'L', rpm: 6, p95: 7200, err: 0.006 },
];

export type Kind = 'latency' | 'errors' | 'throughput';
export type Severity = 'critical' | 'major' | 'resolved';
export type Status = 'healthy' | 'degraded' | 'failing' | 'paused';
export interface FleetEvent { id: number; tick: number; agent: number; severity: Severity; kind: Kind; text: string }

interface Rule { open: boolean; since: number; streak: number; calm: number; mean: number; sd: number; peak: number }
interface AgentState { lat: Rule; err: Rule; thr: Rule; latWin: number[]; rpmWin: number[]; errWin: number[] }

export interface Store {
  /** Tick index of buffer position 0, and of the latest sample. */
  n0: number;
  n: number;
  rpm: number[][];
  p95: number[][];
  err: number[][];
  /** Expected p95 band (baseline mean ± 3σ) at each tick. */
  lo: number[][];
  hi: number[][];
  /** Bit flags per tick: 1 latency, 2 errors, 4 throughput anomaly open. */
  flag: number[][];
  state: AgentState[];
  events: FleetEvent[];
  seq: number;
}

/** Stateless integer hash → [0, 1). */
function rnd(salt: number, i: number, k: number): number {
  let h = Math.imul(SEED ^ Math.imul(salt, 0x27d4eb2d), 0x9e3779b1) ^ Math.imul(i + 1, 0x85ebca6b) ^ Math.imul(k | 0, 0xc2b2ae35);
  h ^= h >>> 16; h = Math.imul(h, 0x7feb352d); h ^= h >>> 15; h = Math.imul(h, 0x846ca68b); h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}
function smooth(salt: number, i: number, t: number, scale: number): number {
  const x = t / scale, k = Math.floor(x), f = x - k, u = f * f * (3 - 2 * f);
  const a = rnd(salt, i, k), b = rnd(salt, i, k + 1);
  return a + (b - a) * u;
}

const BLOCK = 240;
function incident(i: number, n: number): { lat: number; err: number; thr: number } {
  const out = { lat: 1, err: 0, thr: 1 };
  const k = Math.floor(n / BLOCK);
  for (const kk of [k - 1, k]) {
    if (rnd(11, i, kk) > 0.3) continue;
    const start = kk * BLOCK + Math.floor(rnd(12, i, kk) * (BLOCK - 70));
    const dur = 22 + Math.floor(rnd(13, i, kk) * 45);
    if (n < start || n > start + dur) continue;
    const ramp = Math.min(1, (n - start) / 4, (start + dur - n) / 4);
    const type = rnd(14, i, kk), mag = rnd(15, i, kk);
    if (type < 0.5) out.lat *= 1 + ramp * (1.4 + mag * 2.2);
    else if (type < 0.8) out.err += ramp * (0.03 + mag * 0.06);
    else out.thr *= 1 - ramp * (0.55 + mag * 0.3);
  }
  return out;
}

export function sampleAt(i: number, n: number): { rpm: number; p95: number; err: number } {
  const a = AGENTS[i];
  const inc = incident(i, n);
  return {
    rpm: a.rpm * (0.82 + 0.36 * smooth(21, i, n, 50)) * (0.94 + 0.12 * rnd(22, i, n)) * inc.thr,
    p95: a.p95 * (0.88 + 0.24 * smooth(23, i, n, 35)) * (0.95 + 0.1 * rnd(24, i, n)) * inc.lat,
    err: Math.min(0.5, a.err * (0.5 + smooth(25, i, n, 25)) + inc.err + (rnd(26, i, n) < 0.02 ? 0.008 : 0)),
  };
}

const rule = (): Rule => ({ open: false, since: 0, streak: 0, calm: 0, mean: 0, sd: 0, peak: 0 });
const stats = (w: number[]): { mean: number; sd: number } => {
  if (!w.length) return { mean: 0, sd: 0 };
  let s = 0, s2 = 0;
  for (const v of w) { s += v; s2 += v * v; }
  const mean = s / w.length;
  return { mean, sd: Math.sqrt(Math.max(0, s2 / w.length - mean * mean)) };
};
const msFmt = new Intl.NumberFormat('en-GB', { maximumFractionDigits: 0 });
const pctFmt = new Intl.NumberFormat('en-GB', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

function step(st: Store, n: number, record: boolean): void {
  AGENTS.forEach((spec, i) => {
    const a = st.state[i];
    if (spec.paused) { st.rpm[i].push(NaN); st.p95[i].push(NaN); st.err[i].push(NaN); st.lo[i].push(NaN); st.hi[i].push(NaN); st.flag[i].push(0); return; }
    const smp = sampleAt(i, n);
    const emit = (severity: Severity, kind: Kind, text: string) => { if (record) st.events.push({ id: ++st.seq, tick: n, agent: i, severity, kind, text }); };

    // Latency: z-score against a frozen 2-minute baseline; opens after 3 s above 3σ, clears after 5 s below 1.5σ.
    const L = a.lat;
    const base = L.open ? { mean: L.mean, sd: L.sd } : stats(a.latWin);
    const sd = Math.max(base.sd, base.mean * 0.03);
    const z = base.mean ? (smp.p95 - base.mean) / sd : 0;
    if (!L.open) {
      L.streak = z >= 3 ? L.streak + 1 : 0;
      if (L.streak >= 3 && a.latWin.length >= BASELINE / 2) {
        Object.assign(L, { open: true, since: n - 2, calm: 0, mean: base.mean, sd, peak: smp.p95 });
        emit('major', 'latency', `p95 latency ${msFmt.format(smp.p95)} ms, ${z.toFixed(1)}σ above its 2-minute baseline of ${msFmt.format(base.mean)} ms`);
      }
    } else {
      L.peak = Math.max(L.peak, smp.p95);
      L.calm = z < 1.5 ? L.calm + 1 : 0;
      if (L.calm >= 5) { L.open = false; L.streak = 0; emit('resolved', 'latency', `p95 latency back to ${msFmt.format(smp.p95)} ms after ${n - L.since} s (peak ${msFmt.format(L.peak)} ms)`); }
    }
    if (!L.open) { a.latWin.push(smp.p95); if (a.latWin.length > BASELINE) a.latWin.shift(); }

    // Errors: 10-second mean at or above 2 % for 3 s opens (critical); below 1 % for 10 s clears.
    a.errWin.push(smp.err);
    if (a.errWin.length > 10) a.errWin.shift();
    const e10 = stats(a.errWin).mean;
    const E = a.err;
    if (!E.open) {
      E.streak = e10 >= 0.02 ? E.streak + 1 : 0;
      if (E.streak >= 3) { Object.assign(E, { open: true, since: n - 2, calm: 0, peak: e10 }); emit('critical', 'errors', `error rate ${pctFmt.format(e10)} over 10 s (threshold 2.0%)`); }
    } else {
      E.peak = Math.max(E.peak, e10);
      E.calm = e10 < 0.01 ? E.calm + 1 : 0;
      if (E.calm >= 10) { E.open = false; E.streak = 0; emit('resolved', 'errors', `error rate back to ${pctFmt.format(e10)} after ${n - E.since} s (peak ${pctFmt.format(E.peak)})`); }
    }

    // Throughput: under half the frozen 2-minute average for 5 s opens; back above 75 % for 5 s clears.
    const T = a.thr;
    const tBase = T.open ? T.mean : stats(a.rpmWin).mean;
    const ratio = tBase ? smp.rpm / tBase : 1;
    if (!T.open) {
      T.streak = ratio < 0.5 ? T.streak + 1 : 0;
      if (T.streak >= 5 && a.rpmWin.length >= BASELINE / 2) {
        Object.assign(T, { open: true, since: n - 4, calm: 0, mean: tBase, peak: smp.rpm });
        emit('major', 'throughput', `throughput ${msFmt.format(smp.rpm)} runs/min, ${pctFmt.format(ratio)} of its 2-minute average`);
      }
    } else {
      T.calm = ratio >= 0.75 ? T.calm + 1 : 0;
      if (T.calm >= 5) { T.open = false; T.streak = 0; emit('resolved', 'throughput', `throughput recovered to ${msFmt.format(smp.rpm)} runs/min after ${n - T.since} s`); }
    }
    if (!T.open) { a.rpmWin.push(smp.rpm); if (a.rpmWin.length > BASELINE) a.rpmWin.shift(); }

    st.rpm[i].push(smp.rpm); st.p95[i].push(smp.p95); st.err[i].push(smp.err);
    st.lo[i].push(Math.max(0, base.mean - 3 * sd)); st.hi[i].push(base.mean + 3 * sd);
    st.flag[i].push((L.open ? 1 : 0) | (E.open ? 2 : 0) | (T.open ? 4 : 0));
  });
  st.n = n;
}

function trim(st: Store): void {
  const over = st.rpm[0].length - CAPACITY;
  if (over <= 0) return;
  for (const arr of [st.rpm, st.p95, st.err, st.lo, st.hi, st.flag]) for (const a of arr) a.splice(0, over);
  st.n0 += over;
  const keepFrom = st.n0;
  if (st.events.length > 240) st.events.splice(0, st.events.length - 240);
  while (st.events.length && st.events[0].tick < keepFrom - CAPACITY) st.events.shift();
}

export function createStore(now: number): Store {
  const first = now - CAPACITY - WARMUP + 1;
  const mk = () => AGENTS.map(() => [] as number[]);
  const st: Store = {
    n0: first, n: first - 1, rpm: mk(), p95: mk(), err: mk(), lo: mk(), hi: mk(), flag: mk(),
    state: AGENTS.map(() => ({ lat: rule(), err: rule(), thr: rule(), latWin: [], rpmWin: [], errWin: [] })), events: [], seq: 0,
  };
  for (let n = first; n <= now; n++) { step(st, n, n > first + WARMUP); trim(st); }
  return st;
}

/** Append every tick up to `now` (catch-up after a throttled background tab is capped at the buffer size). */
export function advance(st: Store, now: number): void {
  if (now <= st.n) return;
  if (now - st.n > CAPACITY) { Object.assign(st, createStore(now)); return; }
  for (let n = st.n + 1; n <= now; n++) { step(st, n, true); trim(st); }
}

export function statusOf(st: Store, i: number, flags: number): Status {
  if (AGENTS[i].paused) return 'paused';
  return flags & 2 ? 'failing' : flags & 5 ? 'degraded' : 'healthy';
}

/* Switchyard — a freight operator's signal box: lamp-lit agent cells, mono timestamps, one amber for "degraded". */
.root {
  --lm-amber: #8a5000;
  --lm-ok: var(--mk-success, #0a6e4d);
  --lm-bad: var(--mk-danger, #b42318);
  container-type: inline-size;
  min-height: 100dvh;
  padding-bottom: 64px;
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  font-size: 0.875rem;
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
  /* Essential profile: tokens × 0.7, standard easing, no overshoot; press is instant, release takes one tick. */
  --lm-instant: calc(var(--mk-duration-instant, 90ms) * 0.7);
  --lm-fast: calc(var(--mk-duration-fast, 160ms) * 0.7);
  --lm-ease: var(--mk-ease-standard, cubic-bezier(0.2, 0, 0, 1));
  --lm-hover: color-mix(in oklab, var(--mk-ink, #11110f) 6%, transparent);
  --lm-press: color-mix(in oklab, var(--mk-ink, #11110f) 12%, transparent);
}
:global([data-theme='dark']) .root { --lm-amber: #f0b340; }
.wrap { max-width: 1440px; margin: 0 auto; padding-inline: clamp(16px, 2.4cqi, 32px); }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.sub { margin: 4px 0 0; font-size: 0.78rem; line-height: 1.4; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }
.simTag, .simBadge { display: inline-block; padding: 0 5px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 2px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.625rem; line-height: 1.5; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink, #11110f); white-space: nowrap; }
.simBadge { margin-left: 4px; }

/* ── console bar ──────────────────────────────────────────────── */
.bar { background: var(--mk-surface, #fbf9f4); border-bottom: 1px solid var(--mk-line-strong, #11110f); }
@container (min-width: 900px) { .bar { position: sticky; top: 44px; z-index: 20; } }
.barInner { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 24px; padding-block: 10px; }
.brand { margin-right: auto; }
.house { margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.name { margin: 1px 0 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui); font-size: 1.5rem; font-weight: 800; letter-spacing: -0.035em; line-height: 1; }
.nameSub { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 500; letter-spacing: 0.04em; color: var(--mk-ink-muted, #5c5a52); }
.liveBox { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; min-height: 32px; }
.lamp { position: relative; width: 12px; height: 12px; border-radius: 2px; background: var(--lm-ok); color: var(--lm-ok); }
.lamp[data-state='paused'] { background: transparent; box-shadow: inset 0 0 0 2px var(--mk-ink-muted, #5c5a52); color: var(--mk-ink-muted, #5c5a52); }
.lamp[data-state='stale'] { background: var(--lm-amber); color: var(--lm-amber); }
.lamp[data-state='connecting'] { background: var(--mk-ink-muted, #5c5a52); color: var(--mk-ink-muted, #5c5a52); }
.ping { position: absolute; inset: -1px; border: 2px solid currentColor; border-radius: 3px; opacity: 0; pointer-events: none; }
.stateWord { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.stateMeta { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }
.windows { display: inline-flex; align-items: center; gap: 2px; margin: 0; padding: 2px; border: 1px solid var(--mk-line, #11110f24); border-radius: 4px; min-inline-size: 0; }
.windowLegend { float: left; margin: 0 6px 0 8px; padding: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.seg { position: relative; display: block; }
.seg input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
.seg > span { display: grid; place-items: center; height: 28px; padding: 0 10px; border-radius: 3px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); transition: background-color var(--lm-fast) var(--lm-ease), color var(--lm-fast) var(--lm-ease), transform var(--lm-instant) var(--lm-ease); }
.seg input:hover + span { color: var(--mk-ink, #11110f); background: var(--lm-hover); }
.seg input:checked + span { background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); }
/* Pressed: down at once, released in one instant tick. */
.seg input:active + span { transform: scale(0.94); background: var(--lm-press); color: var(--mk-ink, #11110f); transition-duration: 0s; }
.seg input:checked:active + span { background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); }
.seg input:focus-visible + span { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.pause {
  display: inline-flex; align-items: center; gap: 8px; min-height: 36px; padding: 0 14px; border: 1px solid var(--mk-ink, #11110f); border-radius: 4px;
  background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); font: inherit; font-size: 0.8125rem; font-weight: 600;
  transition: background-color var(--lm-fast) var(--lm-ease), color var(--lm-fast) var(--lm-ease), box-shadow var(--lm-fast) var(--lm-ease), transform var(--lm-instant) var(--lm-ease);
}
.pause svg { width: 12px; height: 12px; fill: currentColor; }
.pause:hover:not(:disabled) { background: color-mix(in oklab, var(--mk-ink, #11110f) 84%, var(--mk-surface, #fbf9f4)); box-shadow: 0 0 0 3px var(--lm-hover); }
.pause:active:not(:disabled) { transform: translateY(1px) scale(0.97); box-shadow: none; transition-duration: 0s; }
.pause[aria-pressed='true'] { background: transparent; color: var(--mk-ink, #11110f); }
.pause[aria-pressed='true']:hover { background: var(--lm-hover); }
.pause[aria-pressed='true']:active { background: var(--lm-press); }
.pause:disabled { opacity: 1; background: transparent; color: var(--mk-ink-muted, #5c5a52); border-color: var(--mk-line, #11110f24); cursor: default; }
.pause:focus-visible, .btn:focus-visible, .linkBtn:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }

.intro { max-width: 82ch; margin: 18px 0 0; font-size: 0.875rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── KPIs ─────────────────────────────────────────────────────── */
.kpis { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); margin: 22px 0 0; overflow: hidden; border-block: 1px solid var(--mk-line-strong, #11110f); }
@container (min-width: 760px) { .kpis { grid-template-columns: repeat(5, minmax(0, 1fr)); } }
.kpi { display: grid; align-content: start; gap: 4px; margin: -1px 0 0 -1px; padding: 12px 16px 14px; border-top: 1px solid var(--mk-line, #11110f24); border-left: 1px solid var(--mk-line, #11110f24); min-width: 0; }
.kpi dt { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.kpi dd { margin: 0; }
.kpiValue { font-family: var(--mk-font-display, ui-sans-serif, system-ui); font-size: clamp(1.5rem, 4.4cqi, 2.125rem); font-weight: 700; letter-spacing: -0.03em; line-height: 1.05; font-variant-numeric: tabular-nums lining-nums; white-space: nowrap; }
@container (min-width: 760px) { .kpiValue { font-size: clamp(1.5rem, 2.4cqi, 2.125rem); } }
.of { font-size: 0.55em; font-weight: 500; letter-spacing: 0; color: var(--mk-ink-muted, #5c5a52); }
.kpiNote { font-size: 0.75rem; line-height: 1.35; color: var(--mk-ink-muted, #5c5a52); overflow-wrap: anywhere; }
.kpi[data-alert] .kpiValue { color: var(--lm-bad); }
.dir { font-size: 0.65rem; }

/* ── layout ───────────────────────────────────────────────────── */
.main { display: grid; gap: 32px; margin-top: 28px; }
@container (min-width: 1100px) { .main { grid-template-columns: minmax(0, 1fr) minmax(320px, 400px); gap: 36px; align-items: start; } }
.primary { display: grid; gap: 32px; min-width: 0; }
.panel { min-width: 0; padding-top: 12px; border-top: 1px solid var(--mk-line-strong, #11110f); }
.panelHead { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; }
.panelHead > div { min-width: 0; flex: 1 1 18rem; }
.panelTitle { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui); font-size: 1.125rem; font-weight: 700; letter-spacing: -0.02em; line-height: 1.2; overflow-wrap: anywhere; }
.titleMuted { font-family: var(--mk-font-text, ui-sans-serif, system-ui); font-size: 0.8125rem; font-weight: 400; letter-spacing: 0; color: var(--mk-ink-muted, #5c5a52); }
.btn {
  display: inline-flex; align-items: center; min-height: 32px; padding: 0 12px; border: 1px solid var(--mk-line-strong, #11110f); border-radius: 4px;
  background: transparent; color: inherit; font: inherit; font-size: 0.78rem; font-weight: 500; white-space: nowrap;
  transition: background-color var(--lm-fast) var(--lm-ease), color var(--lm-fast) var(--lm-ease), transform var(--lm-instant) var(--lm-ease);
}
.btn:hover { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); }
.btn:active { transform: translateY(1px) scale(0.97); transition-duration: 0s; }
.linkBtn {
  min-height: 24px; margin-left: 6px; padding: 0 3px; border: 0; border-radius: 2px; background: none; color: inherit; font: inherit; font-weight: 600;
  text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px;
  transition: background-color var(--lm-fast) var(--lm-ease), transform var(--lm-instant) var(--lm-ease);
}
.linkBtn:hover { text-decoration-thickness: 2px; background: var(--lm-hover); }
.linkBtn:active { transform: translateY(1px); background: var(--lm-press); transition-duration: 0s; }

.legend { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 12px 0 0; padding: 0; list-style: none; font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }
.legend li { display: inline-flex; align-items: center; gap: 6px; }
.keyOk { width: 14px; height: 10px; background: color-mix(in oklab, var(--mk-accent, #0a6e4d) 16%, transparent); border-top: 2px solid var(--mk-accent, #0a6e4d); }
.keyFail { width: 14px; height: 10px; background: var(--lm-bad); }
.keyLine { width: 18px; border-top: 2px solid var(--mk-ink, #11110f); }
.keyBand { width: 14px; height: 10px; background: color-mix(in oklab, var(--mk-ink, #11110f) 12%, transparent); }
.keyFlag { width: 18px; border-top: 4px solid var(--lm-bad); border-radius: 2px; }

.plot { position: relative; height: clamp(260px, 28cqi, 360px); margin-top: 6px; }
.plotEmpty { display: grid; place-items: center; height: clamp(220px, 26cqi, 330px); margin-top: 6px; border: 1px dashed var(--mk-line-strong, #11110f); color: var(--mk-ink-muted, #5c5a52); text-align: center; padding: 16px; }
.plotEmpty p { margin: 0; max-width: 40ch; }
.svg { display: block; overflow: visible; }
.grid { stroke: var(--mk-line, #11110f24); shape-rendering: crispEdges; }
.baseline { stroke: var(--mk-line-strong, #11110f); shape-rendering: crispEdges; }
.tick { fill: var(--mk-ink-muted, #5c5a52); font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 10.5px; }
.okArea { fill: color-mix(in oklab, var(--mk-accent, #0a6e4d) 11%, transparent); }
.okLine { fill: none; stroke: var(--mk-accent, #0a6e4d); stroke-width: 1.75; stroke-linejoin: round; }
.failArea { fill: var(--lm-bad); }
.bandLabel { fill: var(--mk-ink-muted, #5c5a52); font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 10px; letter-spacing: 0.06em; text-transform: uppercase; }
.markMajor { fill: var(--lm-amber); }
.markCritical { fill: var(--lm-bad); }
.band { fill: color-mix(in oklab, var(--mk-ink, #11110f) 10%, transparent); }
.agentLine { fill: none; stroke: var(--mk-ink, #11110f); stroke-width: 1.5; stroke-linejoin: round; }
.flagLine { fill: none; stroke: var(--lm-bad); stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; }
.summary { max-width: 82ch; margin: 10px 0 0; font-size: 0.8125rem; line-height: 1.5; text-wrap: pretty; }

/* ── agent grid ───────────────────────────────────────────────── */
.agents { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 148px), 1fr)); gap: 8px; margin: 14px 0 0; padding: 0; list-style: none; }
@container (min-width: 900px) { .agents { grid-template-columns: repeat(auto-fill, minmax(196px, 1fr)); } }
.tile {
  --bar: 0 0 #0000; --sel: 0 0 #0000; --press: 0 0 #0000;
  display: grid; align-content: start; gap: 3px; width: 100%; height: 100%; padding: 10px 12px 12px; text-align: left;
  border: 1px solid var(--mk-line, #11110f24); border-radius: 4px; background: var(--mk-surface, #fbf9f4); color: inherit; font: inherit;
  box-shadow: var(--bar), var(--sel), var(--press);
  transition: border-color var(--lm-fast) var(--lm-ease), background-color var(--lm-fast) var(--lm-ease), box-shadow var(--lm-fast) var(--lm-ease);
}
.tile:hover { border-color: var(--mk-line-strong, #11110f); }
/* Pressed: the cell sinks into the page at once (inset shade), then releases in one instant tick. */
.tile:active { --press: inset 0 2px 5px -2px rgb(0 0 0 / 0.28); background: color-mix(in oklab, var(--mk-surface, #fbf9f4) 88%, var(--mk-ink, #11110f)); transition-duration: 0s; }
.tile:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.tile[aria-pressed='true'] { border-color: var(--mk-ink, #11110f); --sel: inset 0 0 0 1px var(--mk-ink, #11110f); }
.tile[data-status='degraded'] { border-color: var(--lm-amber); --bar: inset 3px 0 0 var(--lm-amber); }
.tile[data-status='failing'] { border-color: var(--lm-bad); --bar: inset 3px 0 0 var(--lm-bad); }
.tile[aria-pressed='true'][data-status] { border-color: var(--mk-ink, #11110f); }
.tile[data-status='paused'] { background: transparent; border-style: dashed; }
.tileHead { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.status { display: inline-flex; align-items: center; gap: 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.status[data-status='healthy'] { color: var(--lm-ok); }
.status[data-status='degraded'] { color: var(--lm-amber); }
.status[data-status='failing'] { color: var(--lm-bad); }
.status[data-status='paused'] { color: var(--mk-ink-muted, #5c5a52); }
.tier { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.625rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.agentId { margin-top: 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.875rem; font-weight: 600; }
.role { font-size: 0.72rem; line-height: 1.3; color: var(--mk-ink-muted, #5c5a52); }
.tileValue { margin-top: 6px; font-family: var(--mk-font-display, ui-sans-serif, system-ui); font-size: 1.5rem; font-weight: 700; letter-spacing: -0.03em; line-height: 1; font-variant-numeric: tabular-nums lining-nums; }
.unit { font-family: var(--mk-font-text, ui-sans-serif, system-ui); font-size: 0.7rem; font-weight: 500; letter-spacing: 0; color: var(--mk-ink-muted, #5c5a52); }
.spark, .sparkEmpty { display: block; width: 100%; height: 36px; margin-top: 4px; }
.sparkLine { fill: none; stroke: var(--mk-ink, #11110f); stroke-width: 1.25; vector-effect: non-scaling-stroke; stroke-linejoin: round; }
.sparkBase { stroke: var(--mk-line-strong, #11110f); stroke-width: 1; vector-effect: non-scaling-stroke; }
.sparkFlag { fill: color-mix(in oklab, var(--lm-bad) 22%, transparent); }
.tileMeta { margin-top: 2px; font-size: 0.72rem; color: var(--mk-ink-muted, #5c5a52); }
.anomaly { justify-self: start; margin-top: 4px; padding: 1px 6px; border-radius: 2px; background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.625rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; }
.tileEmpty { margin-top: 10px; font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }

.glyph { width: 12px; height: 12px; flex: none; fill: currentColor; }
.glyphStroke { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.legend .glyph[data-kind='major'] { color: var(--lm-amber); }
.legend .glyph[data-kind='critical'] { color: var(--lm-bad); }

/* ── tables & log ─────────────────────────────────────────────── */
.tableBox { margin-top: 14px; overflow: auto; border-top: 1px solid var(--mk-line-strong, #11110f); }
.tableBox[hidden] { display: none; }
.tableBox:focus-visible, .log:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.table { width: 100%; min-width: 620px; border-collapse: collapse; font-size: 0.8125rem; }
.table th, .table td { height: 34px; padding: 0 10px; border-bottom: 1px solid var(--mk-line, #11110f24); text-align: left; font-weight: 400; white-space: nowrap; }
.table thead th { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); border-bottom-color: var(--mk-line-strong, #11110f); }
.table tbody th { font-family: var(--mk-font-mono, ui-monospace, monospace); font-weight: 600; }
.table .num { text-align: right; }
.caption { caption-side: bottom; padding: 8px 0; text-align: left; font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }

.logPanel { display: flex; flex-direction: column; }
@container (min-width: 1100px) { .logPanel { position: sticky; top: 120px; } }
.holdNote { min-height: 24px; margin: 8px 0 0; font-size: 0.75rem; color: var(--mk-ink-muted, #5c5a52); }
.holdNote[data-on] { color: var(--mk-ink, #11110f); font-weight: 500; }
/* No overscroll containment: at either end of the log the wheel carries on to the page. */
.log { max-height: 420px; margin-top: 6px; overflow: auto; border-top: 1px solid var(--mk-line, #11110f24); }
@container (min-width: 1100px) { .log { max-height: min(720px, calc(100dvh - 260px)); } }
.events { margin: 0; padding: 0; list-style: none; }
.event { display: grid; grid-template-columns: auto auto minmax(0, 1fr); gap: 2px 10px; padding: 8px 2px; border-bottom: 1px solid var(--mk-line, #11110f24); font-size: 0.78rem; line-height: 1.4; }
.evTime { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.72rem; color: var(--mk-ink-muted, #5c5a52); }
.evSev { display: inline-flex; align-items: center; gap: 5px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; }
.evSev[data-sev='critical'] { color: var(--lm-bad); }
.evSev[data-sev='major'] { color: var(--lm-amber); }
.evSev[data-sev='resolved'] { color: var(--lm-ok); }
.evAgent { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 600; }
.evText { grid-column: 1 / -1; color: var(--mk-ink, #11110f); text-wrap: pretty; }
.event[data-sev='resolved'] .evText { color: var(--mk-ink-muted, #5c5a52); }
.empty { margin: 0; padding: 16px 2px; color: var(--mk-ink-muted, #5c5a52); }

.foot { max-width: 92ch; margin-top: 36px; padding-top: 12px; border-top: 1px solid var(--mk-line, #11110f24); font-size: 0.75rem; line-height: 1.55; color: var(--mk-ink-muted, #5c5a52); }
.foot p { margin: 0; }
.foot strong { color: var(--mk-ink, #11110f); font-weight: 600; }

/* Reduced motion — the OS setting or the app toggle (data-reduced): states apply at once. */
.root[data-reduced] *, .root[data-reduced] *::before, .root[data-reduced] *::after { transition: none !important; animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .root *, .root *::before, .root *::after { transition: none !important; animation: none !important; }
}
